  grp.add(new THREE.Mesh(cloverRelief(FLOWER_H, FZ, .045), petals));
  // back: flat petals with a domed boss; two closed slots with a bridge between them
  const BOSS = .62, BH = .26;
  const bossZ = (x, y) => { const r = Math.hypot(x, y) / BOSS; return r >= 1 ? 0 : -BH * Math.pow(1 - r * r, .75); };
  const CH = { cx: -.06, cy: .07, ang: -.25, w: .24, L: .5, d: .17, bridge: .14 };
  const slot = (x, y) => {
    const dx = x - CH.cx, dy = y - CH.cy, ca = Math.cos(CH.ang), sa = Math.sin(CH.ang);
    const u = dx * ca + dy * sa, v = -dx * sa + dy * ca;
    const hw = CH.w / 2, au = Math.abs(u);
    if (au > CH.L) return 0;
    const ends = Math.min(1, (CH.L - au) / .05), side = Math.min(1, Math.max(0, (hw * Math.sqrt(Math.max(0, 1 - Math.pow(au / CH.L, 6))) - Math.abs(v)) / .025));
    return CH.d * ends * side * side * (3 - 2 * side);
  };
  const backX = (x, y) => { const z = bossZ(x, y); return z + Math.min(slot(x, y), -z); };
