  const sg = cap(R, 48, 180, (x, y) => sz(x + CX, y + CY), 1, false);
  sg.translate(CX, CY, 0);
  const sp = sg.attributes.position, su = sg.attributes.uv;
  for (let i = 0; i < sp.count; i++) su.setXY(i, sp.getX(i) / 2 + .5, sp.getY(i) / 2 + .5);
  const stone = pearlMat(tex(TEX.fFrontClean), loader.load(TEX.fFiber));
