  const sm = new THREE.Mesh(sg, stone);
  sm.onBeforeRender = (r, s, cam) => { stone.userData.uMV.value.setFromMatrix4(new THREE.Matrix4().multiplyMatrices(cam.matrixWorldInverse, sm.matrixWorld)); };
  grp.add(sm);
